%% Recursive list processing
sum([]) -> 0;
sum([H|T]) -> H + sum(T).

my_length([]) -> 0;
my_length([_|T]) -> 1 + my_length(T).

my_map(_, []) -> [];
my_map(F, [H|T]) -> [F(H) | my_map(F, T)].

my_filter(_, []) -> [];
my_filter(Pred, [H|T]) ->
    case Pred(H) of
        true  -> [H | my_filter(Pred, T)];
        false -> my_filter(Pred, T)
    end.
```

Base case handles empty list `[]`, recursive case handles `[Head|Tail]`. This is the fundamental Erlang pattern — match on the structure of the data.
